INSERT INTO `email_notifications` (`id`, `entry_id`, `staff_id`, `subject`, `email_to`, `body`, `status`, `end_date`, `created_at`, `next_dispatch`, `trigger`) VALUES
(43, '00fd1abf9bd296d4f2819832802045c3', 412, 'PPA Details Update Notification 2025-04-14 17:56:29', 'kasiamap@africacdc.org;system@africacdc.org', '<!DOCTYPE html>\n<html>\n  <head>\n    <meta charset=\"UTF-8\">\n    <title>Staff PPA Submission Notification</title>\n    <style type=\"text/css\">\n      body {\n        margin: 0;\n        padding: 0;\n        background-color: #f8f9fa;\n        font-family: Arial, sans-serif;\n      }\n      .container {\n        max-width: 650px;\n        margin: 0 auto;\n        background: #ffffff;\n        padding: 20px;\n        border: 1px solid #dddddd;\n      }\n      .header {\n        text-align: center;\n        padding: 15px 0;\n      }\n      .header img {\n        height: 80px;\n      }\n      .content {\n        padding: 20px;\n      }\n      h1 {\n        color: #333333;\n      }\n      p {\n        line-height: 1.6;\n        color: #444444;\n      }\n      .btn {\n        display: inline-block;\n        background-color: #007b5e;\n        color: #ffffff;\n        padding: 10px 18px;\n        border-radius: 5px;\n        text-decoration: none;\n        margin-top: 15px;\n      }\n      .btn:hover {\n      background-color: #005844; /* optional darker shade */\n      color: #ffffff !important; /* ensure text remains visible */\n      text-decoration: none;\n      }\n      .footer {\n        text-align: center;\n        font-size: 12px;\n        color: #777777;\n        margin-top: 30px;\n      }\n    </style>\n  </head>\n  <body>\n    <div class=\"container\">\n      <!-- Header -->\n      <div class=\"header\">\n        <img src=\"https://khub.africacdc.org/storage/uploads/config/fcb24779b37db15ee15fd4a32eaab0ac.png\" alt=\"Africa CDC\">\n      </div>\n\n      <!-- Main Content -->\n      <div class=\"content\">\n        <h1>Staff PPA Submission</h1>\n        <p>Dear Mr Patrick Kasiama,</p>\n        <p>\n          This is to inform you that <strong>Mr Dennis  Kibiye </strong> has submitted their Performance Planning and Appraisal (PPA) form for the period: <strong>January 2025 to December 2025</strong>.\n        </p>\n        <p>\n          Please review the submission and take the necessary action at your earliest convenience.\n        </p>\n\n        <a href=\"http://localhost/staff/performance/view_ppa/e6936ca50cb39201b4f1cbbb95129d91/74\" class=\"btn\" style=\"color:#fff !important;\">Review Submitted PPA</a>\n\n\n        <p>\n          Best regards,<br>\n          <strong>HR Team, Africa CDC</strong>\n        </p>\n      </div>\n\n      <!-- Footer -->\n      <div class=\"footer\">\n        &copy; 2025 Africa CDC. All rights reserved.\n      </div>\n    </div>\n  </body>\n</html>\n', 0, '2025-04-14', '2025-04-14 17:56:29', '2025-04-14 17:56:29', 'Mr Andrew Agaba'),
(44, '00fd1abf9bd296d4f2819832802045c3', 74, 'PPA Details Update Notification 2025-04-14 17:57:13', 'kibiyed@africacdc.org;system@africacdc.org', '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>PPA Update Notification</title>\n  <style type=\"text/css\">\n    body {\n      margin: 0;\n      padding: 0;\n      background-color: #f8f9fa;\n      font-family: Arial, sans-serif;\n    }\n    .container {\n      max-width: 650px;\n      margin: 0 auto;\n      background-color: #ffffff;\n      padding: 20px;\n      border: 1px solid #dddddd;\n    }\n    .header {\n      text-align: center;\n      padding: 15px 0;\n    }\n    .header img {\n      height: 80px;\n    }\n    .content {\n      padding: 20px 0;\n    }\n    h1 {\n      color: #333333;\n      font-size: 20px;\n      margin-bottom: 20px;\n    }\n    p {\n      line-height: 1.6;\n      color: #444444;\n      font-size: 14px;\n    }\n    .btn {\n      display: inline-block;\n      background-color: #007b5e;\n      color: #ffffff !important;\n      padding: 10px 18px;\n      border-radius: 5px;\n      text-decoration: none;\n      margin-top: 20px;\n    }\n    .btn:hover {\n    background-color: #005844; /* optional darker shade */\n    color: #ffffff !important; /* ensure text remains visible */\n    text-decoration: none;\n    }\n    .footer {\n      text-align: center;\n      font-size: 12px;\n      color: #777777;\n      margin-top: 30px;\n      padding-top: 15px;\n      border-top: 1px solid #dddddd;\n    }\n  </style>\n</head>\n<body>\n  <div class=\"container\">\n    <!-- Header -->\n    <div class=\"header\">\n      <img src=\"https://khub.africacdc.org/storage/uploads/config/fcb24779b37db15ee15fd4a32eaab0ac.png\" alt=\"Africa CDC Logo\">\n    </div>\n\n    <!-- Main Content -->\n    <div class=\"content\">\n      <h1>Your PPA Has Been Updated</h1>\n\n      <p>Dear <strong>Mr Dennis  Kibiye </strong>,</p>\n\n      <p>\n        We would like to inform you that your submitted PPA for the period: \n        <strong>January 2025 to December 2025</strong> has been <strong>updated</strong> by your supervisor <strong>Mr Patrick Kasiama</strong>.\n      </p>\n\n      <p>\n        These updates may include feedback, changes in objectives, KPIs, timelines, and trainings.\n      </p>\n\n\n      <p>\n        <a href=\"http://localhost/staff/performance/view_ppa/e6936ca50cb39201b4f1cbbb95129d91/74\" class=\"btn\">View Updated PPA</a>\n      </p>\n\n      <p>\n        Best regards,<br>\n        <strong>HR Team, Africa CDC</strong>\n      </p>\n    </div>\n\n    <!-- Footer -->\n    <div class=\"footer\">\n      &copy; 2025 Africa CDC. All rights reserved.\n    </div>\n  </div>\n</body>\n</html>\n', 0, '2025-04-14', '2025-04-14 17:57:13', '2025-04-14 17:57:13', 'Mr Andrew Agaba'),
