(632, '2025-04-19', 441, 'Staff PPA Reminder: Submit your PPA (January-2025-to-December-2025)', 'sylvanae@africacdc.org;system@africacdc.org', '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>PPA Submission Reminder</title>\n  <style type=\"text/css\">\n    body {\n      font-family: Arial, sans-serif;\n      font-size: 14px;\n      color: #333333;\n      background-color: #f4f4f4;\n      margin: 0;\n      padding: 0;\n    }\n\n    .container {\n      width: 100%;\n      max-width: 650px;\n      margin: 0 auto;\n      background-color: #ffffff;\n      border: 1px solid #dddddd;\n      padding: 30px;\n      box-shadow: 0 0 10px rgba(0,0,0,0.05);\n      border-radius: 8px;\n    }\n\n    .header {\n      text-align: center;\n      margin-bottom: 10px;\n    }\n\n    .header img {\n      max-height: 70px;\n    }\n\n    .header h1 {\n      margin: 10px 0 0 0;\n      font-size: 22px;\n      color: #119A48;\n    }\n\n    .content {\n      padding: 20px 0;\n      line-height: 1.6;\n    }\n\n    .btn {\n      display: inline-block;\n      padding: 10px 20px;\n      background-color: #119A48;\n      color: #ffffff;\n      text-decoration: none;\n      border-radius: 5px;\n      font-weight: bold;\n      margin-top: 15px;\n    }\n\n    .footer {\n      font-size: 12px;\n      color: #888888;\n      text-align: center;\n      padding-top: 30px;\n      border-top: 1px solid #eeeeee;\n    }\n\n    @media only screen and (max-width: 600px) {\n      .container {\n        padding: 20px;\n      }\n\n      .btn {\n        width: 100%;\n        text-align: center;\n      }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"container\">\n    <!-- Header -->\n    <div class=\"header\">\n      <img src=\"https://khub.africacdc.org/storage/uploads/config/fcb24779b37db15ee15fd4a32eaab0ac.png\" alt=\"Africa CDC Logo\">\n      <h1>PPA Submission Reminder</h1>\n    </div>\n\n    <!-- Body Content -->\n    <div class=\"content\">\n      <p>Dear Ms Efire Sylvana,</p>\n\n      <p>This is a kind reminder to submit your <strong>Performance Planning and Appraisal (PPA)</strong> form for the period <strong>January-2025-to-December-2025</strong>.</p>\n\n      <p>The extended deadline for submission is <strong>April 15, 2025</strong>. Kindly ensure that your PPA is completed and submitted before this date.</p>\n\n      <p>You can access the PPA form by logging into the staff portal:</p>\n\n      <p>\n        <a href=\"https://tools.africacdc.org/staff/performance\" class=\"btn\">Submit My PPA</a>\n      </p>\n\n      <p>If you have already submitted your PPA, kindly ignore this reminder.</p>\n\n      <p>Thank you for your attention and commitment.</p>\n\n      <p>Best regards,<br>\n      <strong>Human Resources</strong></p>\n    </div>\n\n    <!-- Footer -->\n    <div class=\"footer\">\n      &copy; 2025 Africa CDC. All rights reserved.\n    </div>\n  </div>\n</body>\n</html>\n', 0, '2025-04-19', '2025-04-19 23:13:30', '2025-04-19 00:00:00', 'Staff Portal System'),
(662, '0fc4cea6b194fd030c80e32ef531648b', 558, 'PPA Details Update Notification 2025-04-20 01:13:30', 'AndrewA@africacdc.org;system@africacdc.org', '<!DOCTYPE html>\n<html>\n<head>\n  <meta charset=\"UTF-8\">\n  <title>PPA Update Notification</title>\n  <style type=\"text/css\">\n    body {\n      margin: 0;\n      padding: 0;\n      background-color: #f8f9fa;\n      font-family: Arial, sans-serif;\n    }\n    .container {\n      max-width: 650px;\n      margin: 0 auto;\n      background-color: #ffffff;\n      padding: 20px;\n      border: 1px solid #dddddd;\n    }\n    .header {\n      text-align: center;\n      padding: 15px 0;\n    }\n    .header img {\n      height: 80px;\n    }\n    .content {\n      padding: 20px 0;\n    }\n    h1 {\n      color: #333333;\n      font-size: 20px;\n      margin-bottom: 20px;\n    }\n    p {\n      line-height: 1.6;\n      color: #444444;\n      font-size: 14px;\n    }\n    .btn {\n      display: inline-block;\n      background-color: #007b5e;\n      color: #ffffff !important;\n      padding: 10px 18px;\n      border-radius: 5px;\n      text-decoration: none;\n      margin-top: 20px;\n    }\n    .btn:hover {\n    background-color: #005844; /* optional darker shade */\n    color: #ffffff !important; /* ensure text remains visible */\n    text-decoration: none;\n    }\n    .footer {\n      text-align: center;\n      font-size: 12px;\n      color: #777777;\n      margin-top: 30px;\n      padding-top: 15px;\n      border-top: 1px solid #dddddd;\n    }\n  </style>\n</head>\n<body>\n  <div class=\"container\">\n    <!-- Header -->\n    <div class=\"header\">\n      <img src=\"https://khub.africacdc.org/storage/uploads/config/fcb24779b37db15ee15fd4a32eaab0ac.png\" alt=\"Africa CDC Logo\">\n    </div>\n\n    <!-- Main Content -->\n    <div class=\"content\">\n      <h1>Your PPA Has Been Updated</h1>\n\n      <p>Dear <strong>Mr Andrew Agaba</strong>,</p>\n\n      <p>\n        We would like to inform you that your submitted PPA for the period: \n        <strong>January 2025 to December 2025</strong> has been <strong>updated</strong> by your supervisor <strong>Mr Dennis  Kibiye </strong>.\n      </p>\n\n      <p>\n        These updates may include feedback, changes in objectives, KPIs, timelines, and trainings.\n      </p>\n\n\n      <p>\n        <a href=\"http://localhost/staff/performance/view_ppa/007837fdc355524026fee5e204c6e21d/558\" class=\"btn\">View Updated PPA</a>\n      </p>\n\n      <p>\n        Best regards,<br>\n        <strong>HR Team, Africa CDC</strong>\n      </p>\n    </div>\n\n    <!-- Footer -->\n    <div class=\"footer\">\n      &copy; 2025 Africa CDC. All rights reserved.\n    </div>\n  </div>\n</body>\n</html>\n', 0, '2025-04-20', '2025-04-20 01:13:30', '2025-04-20 01:13:30', 'Mr Dennis  Kibiye '),
