(672, '660f5e656c17b984fff446b65bcda7b8', 205, 'Contract Notice', 'tugumea@africacdc.org;hr@africacdc.org;gikwan@africacdc.org;riekl@africacdc.org', '<!DOCTYPE html>\n<html>\n  <head>\n    <meta charset=\"UTF-8\">\n    <title>New Contract Award</title>\n    <style type=\"text/css\">\n      body {\n        margin: 0; \n        padding: 0; \n        background-color: #f4f4f4; \n        font-family: Arial, sans-serif;\n      }\n      .container {\n        width: 100%; \n        max-width: 600px; \n        margin: 0 auto; \n        background: #ffffff; \n        padding: 20px;\n      }\n      .header {\n        text-align: center; \n        padding: 10px 0;\n      }\n      .header img {\n        max-width: 150px;\n      }\n      .content {\n        padding: 20px;\n      }\n      .footer {\n        text-align: center; \n        font-size: 12px; \n        color: #888888; \n        padding: 10px 0;\n      }\n      h1 {\n        color: #2A2A2A;\n      }\n      p {\n        line-height: 1.5;\n      }\n      .btn {\n        display: inline-block; \n        background-color: #4CAF50; \n        color: #ffffff; \n        padding: 10px 20px;\n        text-decoration: none; \n        border-radius: 5px;\n      }\n    </style>\n  </head>\n  <body>\n    <div class=\"container\">\n      <!-- Header with Africa CDC logo -->\n      <div class=\"header\">\n        <img src=\"https://khub.africacdc.org/storage/uploads/config/fcb24779b37db15ee15fd4a32eaab0ac.png\" alt=\"Africa CDC\">\n      </div>\n      <!-- Email Content -->\n      <div class=\"content\">\n        <h1>Congratulations on Your New Contract!</h1>\n        <p>Dear Mr. Abdulaziz Tugume,</p>\n        <p>\n          We are pleased to announce your new contract, which starts on 2025-04-01 and concludes on 2025-04-30.\n        </p>\n        <p>\n          We value your contributions and trust you will continue to excel in your role. \n        </p>\n        <p>\n          Thank you for your dedication.\n        </p>\n        <p>\n          Sincerely,<br>\n          HR Team, Africa CDC\n        </p>\n        <!-- Optional: Link to portal or contract details -->\n        <!-- <p>\n          <a href=\"/staff\" class=\"btn\">View Contract Details</a>\n        </p> -->\n      </div>\n      <!-- Footer -->\n      <div class=\"footer\">\n        <p>&copy; 2025 Africa CDC. All Rights Reserved.</p>\n      </div>\n    </div>\n  </body>\n</html>\n', 0, '2025-04-22', '2025-04-22 13:16:58', '2025-04-22 13:16:58', 'Mr Andrew Agaba'),
(673, 'f2aece8b4447053f0567551034a2e179', 456, 'Contract Notice', 'AlhatmyA@africacdc.org;hr@africacdc.org;gikwan@africacdc.org;merawia@africacdc.org', '<!DOCTYPE html>\n<html>\n  <head>\n    <meta charset=\"UTF-8\">\n    <title>New Contract Award</title>\n    <style type=\"text/css\">\n      body {\n        margin: 0; \n        padding: 0; \n        background-color: #f4f4f4; \n        font-family: Arial, sans-serif;\n      }\n      .container {\n        width: 100%; \n        max-width: 600px; \n        margin: 0 auto; \n        background: #ffffff; \n        padding: 20px;\n      }\n      .header {\n        text-align: center; \n        padding: 10px 0;\n      }\n      .header img {\n        max-width: 150px;\n      }\n      .content {\n        padding: 20px;\n      }\n      .footer {\n        text-align: center; \n        font-size: 12px; \n        color: #888888; \n        padding: 10px 0;\n      }\n      h1 {\n        color: #2A2A2A;\n      }\n      p {\n        line-height: 1.5;\n      }\n      .btn {\n        display: inline-block; \n        background-color: #4CAF50; \n        color: #ffffff; \n        padding: 10px 20px;\n        text-decoration: none; \n        border-radius: 5px;\n      }\n    </style>\n  </head>\n  <body>\n    <div class=\"container\">\n      <!-- Header with Africa CDC logo -->\n      <div class=\"header\">\n        <img src=\"https://khub.africacdc.org/storage/uploads/config/fcb24779b37db15ee15fd4a32eaab0ac.png\" alt=\"Africa CDC\">\n      </div>\n      <!-- Email Content -->\n      <div class=\"content\">\n        <h1>Congratulations on Your New Contract!</h1>\n        <p>Dear Dr Abdulrahman Kassim,</p>\n        <p>\n          We are pleased to announce your new contract, which starts on 2025-04-01 and concludes on 2025-12-31.\n        </p>\n        <p>\n          We value your contributions and trust you will continue to excel in your role. \n        </p>\n        <p>\n          Thank you for your dedication.\n        </p>\n        <p>\n          Sincerely,<br>\n          HR Team, Africa CDC\n        </p>\n        <!-- Optional: Link to portal or contract details -->\n        <!-- <p>\n          <a href=\"/staff\" class=\"btn\">View Contract Details</a>\n        </p> -->\n      </div>\n      <!-- Footer -->\n      <div class=\"footer\">\n        <p>&copy; 2025 Africa CDC. All Rights Reserved.</p>\n      </div>\n    </div>\n  </body>\n</html>\n', 0, '2025-04-22', '2025-04-22 13:19:37', '2025-04-22 13:19:37', 'Mr Andrew Agaba');
